// src/nuxt.ts
import { computed, useFetch, useState } from "#imports";
function createCurrentAuthUrl(endpoint, guard) {
  if (!guard) {
    return endpoint;
  }
  const base = endpoint.startsWith("http://") || endpoint.startsWith("https://") ? new URL(endpoint) : new URL(endpoint, "https://holo.local");
  base.searchParams.set("guard", guard);
  if (endpoint.startsWith("http://") || endpoint.startsWith("https://")) {
    return base.toString();
  }
  return `${base.pathname}${base.search}${base.hash}`;
}
function useCurrentAuthFetch(requestUrl, stateKey) {
  return useFetch(requestUrl, {
    key: `${stateKey}:request`
  });
}
async function useAuth(options = {}) {
  const endpoint = options.endpoint ?? "/api/auth/user";
  const requestUrl = createCurrentAuthUrl(endpoint, options.guard);
  const stateKey = options.key ?? `holo-auth:${requestUrl}`;
  const currentAuthenticated = useState(`${stateKey}:authenticated`, () => false);
  const currentProvider = useState(`${stateKey}:provider`, () => null);
  const currentUser = useState(`${stateKey}:user`, () => null);
  const authenticated = computed(() => currentAuthenticated.value);
  const { data, refresh } = await useCurrentAuthFetch(requestUrl, stateKey);
  currentAuthenticated.value = data.value?.authenticated ?? false;
  currentProvider.value = data.value?.provider ?? null;
  currentUser.value = data.value?.user ?? null;
  return {
    authenticated,
    provider: currentProvider,
    user: currentUser,
    async refreshUser() {
      await refresh();
      currentAuthenticated.value = data.value?.authenticated ?? false;
      currentProvider.value = data.value?.provider ?? null;
      currentUser.value = data.value?.user ?? null;
      return currentUser.value;
    }
  };
}

export {
  useAuth
};
